 10	    /// <summary>
 11	    /// Singleton service for loading and managing JSON-based localization.
 12	    /// Provides thread-safe access to translated strings with culture switching support.
 13	    /// </summary>
 14	    public sealed class LocalizationService : ObservableObject
 15	    {
 16	        private static readonly Lazy<LocalizationService> _instance = 
 17	            new Lazy<LocalizationService>(() => new LocalizationService());
 18	
 19	        private readonly object _lock = new object();
 20	        private Dictionary<string, Dictionary<string, string>> _translations = new();
 21	        private string _currentCulture = "en-US";
 22	        private string? _sessionStartCulture; // Culture that was active when app started
 23	        private readonly string _localesPath;
 24	
 25	        /// <summary>
 26	        /// Gets the singleton instance of the LocalizationService.
 27	        /// </summary>
 28	        public static LocalizationService Instance => _instance.Value;
 29	
 30	        /// <summary>
 31	        /// Event raised when the current culture changes.
 32	        /// </summary>
 33	        public event EventHandler? CultureChanged;
 34	
 35	        /// <summary>
 36	        /// Gets the current culture name (e.g., "en-US", "de-DE", "fr-FR").
 37	        /// </summary>
 38	        public string CurrentCulture
 39	        {
 40	            get => _currentCulture;
 41	            private set => SetProperty(ref _currentCulture, value);
 42	        }
 43	        
 44	        /// <summary>
 45	        /// Gets the culture that was active when the application session started.
 46	        /// This is set once during initialization and remains constant for the session.
 47	        /// </summary>
 48	        public string SessionStartCulture => _sessionStartCulture ?? _currentCulture;
 49	
 50	        private LocalizationService()
 51	        {
 52	            // Determine locales path relative to executable
 53	            var exeDir = AppDomain.CurrentDomain.BaseDirectory;
 54	            _localesPath = Path.Combine(exeDir, "ViewTexts", "Locales");
 55	            
 56	            // Detect system culture and load appropriate language
 57	            var systemCulture = DetectSystemCulture();
 58	            _currentCulture = systemCulture;
 59	            _sessionStartCulture = systemCulture; // Set session start culture
 60	            LoadCulture(_currentCulture);
 61	        }
 62	
 63	        /// <summary>
 64	        /// Detects the system culture and returns the appropriate supported culture.
 65	        /// Falls back to "en-US" if system culture is not supported.
 66	        /// </summary>
 67	        private string DetectSystemCulture()
 68	        {
 69	            try
 70	            {
 71	                var currentCulture = CultureInfo.CurrentUICulture;
 72	                var cultureName = currentCulture.Name; // e.g., "fr-FR", "de-DE"
 73	                
 74	                // Check if we have a translation for this culture
 75	                var culturePath = Path.Combine(_localesPath, $"{cultureName}.json");
 76	                if (File.Exists(culturePath))
 77	                {
 78	                    return cultureName;
 79	                }
 80	                
 81	                // Try parent culture (e.g., "fr" if "fr-FR" not found)
 82	                if (currentCulture.Parent != null && !string.IsNullOrEmpty(currentCulture.Parent.Name))
 83	                {
 84	                    var parentCulture = currentCulture.Parent.Name;
 85	                    
 86	                    // Build parent culture map dynamically from locale files
 87	                    var parentMap = BuildParentCultureMap();
 88	                    
 89	                    if (parentMap.TryGetValue(parentCulture, out var mappedCulture))
 90	                    {
 91	                        var mappedPath = Path.Combine(_localesPath, $"{mappedCulture}.json");
 92	                        if (File.Exists(mappedPath))
 93	                        {
 94	                            return mappedCulture;
 95	                        }
 96	                    }
 97	                }
 98	                
 99	                // Default to English if no match found
100	                return "en-US";

101	            }
102	            catch
103	            {
104	                // If detection fails, default to English
105	                return "en-US";
106	            }
107	        }
