109	        /// <summary>
110	        /// Gets a translated string from the specified section and key.
111	        /// </summary>
112	        /// <param name="section">The JSON section (e.g., "MainWindow", "ErrorDialog")</param>
113	        /// <param name="key">The string key within the section</param>
114	        /// <returns>The translated string, or a fallback if not found</returns>
115	        public string GetString(string section, string key)
116	        {
117	            lock (_lock)
118	            {
119	                var fullKey = $"{section}.{key}";
120	                
121	                if (_translations.TryGetValue(fullKey, out var value))
122	                {
123	                    return value.GetValueOrDefault(_currentCulture, $"[{fullKey}]");
124	                }
125	
126	                return $"[{fullKey}]";
127	            }
128	        }
