130	        /// <summary>
131	        /// Gets a formatted translated string with arguments.
132	        /// </summary>
133	        /// <param name="section">The JSON section</param>
134	        /// <param name="key">The string key</param>
135	        /// <param name="args">Format arguments</param>
136	        /// <returns>The formatted translated string</returns>
137	        public string GetString(string section, string key, params object[] args)
138	        {
139	            var template = GetString(section, key);
140	            
141	            try
142	            {
143	                return string.Format(template, args);
144	            }
145	            catch (FormatException)
146	            {
147	                // If format fails, return template with args appended
148	                return $"{template} [{string.Join(", ", args)}]";
149	            }
150	        }
